import sys
from collections import Counter, defaultdict
from pathlib import Path


def read_fasta(path):
    seqs = []
    with open(path) as fh:
        name = None
        parts = []
        for line in fh:
            if line.startswith(">"):
                if name is not None:
                    seqs.append("".join(parts).strip())
                name = line[1:].strip()
                parts = []
            else:
                parts.append(line.strip())
        if name is not None:
            seqs.append("".join(parts).strip())
    return seqs


def kmers(seq, k):
    return [seq[i:i+k] for i in range(len(seq)-k+1)]


def canonical_kmer_counts(seqs, k):
    counts = Counter()
    for s in seqs:
        if len(s) < k:
            continue
        counts.update(set(kmers(s, k)))
    return counts


def main():
    mix_path, endo_path, exo_path, out_path, class_path = sys.argv[1:6]
    mix = read_fasta(mix_path)
    endo = read_fasta(endo_path)
    exo = read_fasta(exo_path)

